// Process successful pipeline execution output
const startTime = msg.startTime || Date.now();
const executionTime = Date.now() - startTime;

msg.pipeline_result = {
    success: true,
    script: 'manual_pipeline_trigger.py',
    execution_time_ms: executionTime,
    output: msg.payload,
    timestamp: new Date().toISOString()
};

// Extract progress information from stdout
const output = msg.payload || '';
const progressIndicators = [
    'Starting manual pipeline',
    'Data relationships pipeline',
    'Performance tracker',
    'Horse mapping pipeline',
    'Pipeline completed successfully'
];

let currentStep = 'Unknown';
let progressPercent = 0;

for (let i = 0; i < progressIndicators.length; i++) {
    if (output.includes(progressIndicators[i])) {
        currentStep = progressIndicators[i];
        progressPercent = ((i + 1) / progressIndicators.length) * 100;
    }
}

msg.pipeline_result.progress = {
    currentStep: currentStep,
    progressPercent: progressPercent
};

// Set status for dashboard
msg.statusCode = 200;
msg.headers = { 'Content-Type': 'application/json' };

node.status({fill: "green", shape: "dot", text: `✅ Pipeline completed in ${executionTime}ms`});

return msg;

// Process pipeline execution errors
const startTime = msg.startTime || Date.now();
const executionTime = Date.now() - startTime;

// Classify error type
const stderr = msg.payload || '';
let errorType = 'general_error';

if (stderr.includes('TimeoutExpired')) errorType = 'timeout';
else if (stderr.includes('connection') || stderr.includes('database')) errorType = 'connection_error';
else if (stderr.includes('FileNotFoundError')) errorType = 'missing_file';
else if (stderr.includes('PermissionError')) errorType = 'permission_error';

msg.pipeline_result = {
    success: false,
    script: 'manual_pipeline_trigger.py',
    execution_time_ms: executionTime,
    error: msg.payload,
    error_type: errorType,
    timestamp: new Date().toISOString()
};

// Check if retry is appropriate
const retryCount = msg.retryCount || 0;
const maxRetries = 3;
const shouldRetry = retryCount < maxRetries && errorType !== 'timeout';

if (shouldRetry) {
    msg.retryCount = retryCount + 1;
    msg.delay = Math.pow(2, retryCount) * 1000; // Exponential backoff
    node.status({fill: "yellow", shape: "ring", text: `⚠️ Retry ${retryCount + 1}/${maxRetries}`});
    return [null, msg]; // Send to retry path
}

// Set error status for dashboard
msg.statusCode = 500;
msg.headers = { 'Content-Type': 'application/json' };

node.status({fill: "red", shape: "dot", text: `❌ Pipeline failed: ${errorType}`});

return [msg, null]; // Send to error handler

// Process pipeline execution exit code
const startTime = msg.startTime || Date.now();
const executionTime = Date.now() - startTime;
const exitCode = msg.payload || 0;

msg.pipeline_result = {
    script: 'manual_pipeline_trigger.py',
    execution_time_ms: executionTime,
    exit_code: exitCode,
    success: exitCode === 0,
    timestamp: new Date().toISOString()
};

if (exitCode === 0) {
    node.status({fill: "green", shape: "dot", text: `✅ Exit code 0 (${executionTime}ms)`});
} else {
    node.status({fill: "red", shape: "dot", text: `❌ Exit code ${exitCode}`});
}

return msg;

// Store pipeline execution results for dashboard display
const results = global.get('pipeline_results') || [];

// Add current result to history
results.push(msg.pipeline_result);

// Keep only last 10 results
if (results.length > 10) {
    results.splice(0, results.length - 10);
}

// Store updated results
global.set('pipeline_results', results);
global.set('last_pipeline_result', msg.pipeline_result);

node.status({fill: "blue", shape: "dot", text: `📝 Stored result (${results.length} total)`});

return msg;

// Handle API requests to trigger pipeline
msg.startTime = Date.now();
msg.payload = {
    action: 'trigger_pipeline',
    source: 'api',
    timestamp: new Date().toISOString(),
    request_id: msg._msgid
};

node.status({fill: "blue", shape: "dot", text: `🌐 API trigger: ${msg._msgid.substring(0,8)}`});

return msg;

// Send immediate API response
msg.payload = {
    success: true,
    message: 'Pipeline triggered successfully',
    request_id: msg._msgid,
    timestamp: new Date().toISOString()
};

msg.statusCode = 202; // Accepted
msg.headers = { 'Content-Type': 'application/json' };

return msg;

// Return current pipeline status and recent results
const lastResult = global.get('last_pipeline_result');
const results = global.get('pipeline_results') || [];

msg.payload = {
    success: true,
    last_execution: lastResult || null,
    recent_results: results,
    total_executions: results.length,
    timestamp: new Date().toISOString()
};

msg.statusCode = 200;
msg.headers = { 'Content-Type': 'application/json' };

return msg;
